mapper.select:
select x.cscene_id as csceneId, x.type as elementType, count(x.type) as elementTypeCount, SUM(x.cpu) as cpu, SUM(x.ram) as ram, SUM(x.disk) as disk from (select a.id as cscene_id, b.node_id as node_id, CASE WHEN b.cpu = 0 and c.image_type = 'container' THEN #{cpu} ELSE b.cpu END as cpu, CASE WHEN b.ram = 0 and c.image_type = 'container' THEN #{ram} ELSE b.ram END as ram, CASE WHEN b.disk = 0 and c.image_type = 'container' THEN #{disk} ELSE b.disk END as disk, b.type as type, c.image_type as image_type from mp_cscene_cscene a, mp_scene_scene_config_element b, mp_sceneplugincloud_scene_config_element c where a.id in
#{item}
and a.scene_config = b.scene and b.scene = c.scene and b.node_id = c.scene_element) as x GROUP BY x.cscene_id , x.type;

select a.id as csceneId , #{cpu} as cpu , #{ram} as ram , #{disk} as disk
from mp_cscene_cscene a,
mp_scenepluginflow_scene_config b
where a.scene_config = b.scene
and a.id in

    #{item}
